using System.Globalization;
using System.IO.Compression;
using System.Net;
using System.Text;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
using System.Xml;
using System.Xml.Linq;
namespace MyProjectManagement;
public static class ChangeRequestWord {
 static readonly XNamespace W="http://schemas.openxmlformats.org/wordprocessingml/2006/main";
 static string ParagraphText(XElement p)=>string.Concat(p.Descendants().Where(e=>e.Name==W+"t"||e.Name==W+"br"||e.Name==W+"tab").Select(e=>e.Name==W+"t"?e.Value:e.Name==W+"br"?"\n":"\t"));
 static string Text(XElement x)=>string.Join("\n",x.Descendants(W+"p").Select(ParagraphText).Where(t=>t.Trim()!="")).Trim();
 static string Label(string x)=>Regex.Replace(x.ToLowerInvariant(),"[^a-z0-9]","");
 public static string NumberKey(string value)=>Regex.Replace(value.Normalize(NormalizationForm.FormKC).Trim(),@"\s+"," ").ToUpperInvariant();
 public static (string number,string revision) SplitNumber(string value){var m=Regex.Match(value.Trim(),@"^(.*?)\s+Rev(?:ision)?[\s.:_-]+([A-Za-z0-9][A-Za-z0-9._-]{0,29})\s*$",RegexOptions.IgnoreCase);return m.Success?(m.Groups[1].Value.Trim(),m.Groups[2].Value):(value.Trim(),"");}
 static XDocument Xml(ZipArchiveEntry entry){using var s=entry.Open();using var reader=XmlReader.Create(s,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=4*1024*1024});return XDocument.Load(reader);}
 static XDocument Document(byte[] bytes){J.Require(bytes.Length is >0 and <=5242880,"Upload a .docx document up to 5 MB",400);try{using var zip=new ZipArchive(new MemoryStream(bytes),ZipArchiveMode.Read);J.Require(zip.Entries.Count<=2000&&zip.Entries.Select(x=>x.FullName).Distinct().Count()==zip.Entries.Count&&zip.Entries.Sum(e=>e.Length)<=30*1024*1024,"Document archive is too complex or oversized",400);J.Require(!zip.Entries.Any(e=>e.FullName.Contains("vbaProject",StringComparison.OrdinalIgnoreCase)),"Macros are not supported",400);var entry=zip.GetEntry("word/document.xml");J.Require(entry is not null&&entry.Length<=4*1024*1024,"Invalid Word document",400);var document=Xml(entry!);J.Require(document.Root?.Name==W+"document"&&document.Root.Element(W+"body") is not null,"Invalid Word document body",400);return document;}catch(InvalidDataException){throw new ApiError(400,"Upload a valid Word .docx");}catch(XmlException){throw new ApiError(400,"Invalid Word XML");}}
 static List<XElement> Tables(XDocument d)=>d.Root!.Element(W+"body")!.Elements(W+"tbl").ToList();
 static (XElement header,XElement details) FormTables(XDocument d){var tables=Tables(d);var h=tables.FirstOrDefault(t=>t.Elements(W+"tr").Any(r=>Label(Text(r.Elements(W+"tc").FirstOrDefault()??new XElement("x"))).StartsWith("changerequestno")));var detailTables=tables.Where(t=>t.Elements(W+"tr").Any(r=>r.Elements(W+"tc").Any(c=>Label(Text(c)).Contains("clientrequirement")))).ToList();J.Require(detailTables.Count<=1,"Use one requirements table with Module headings, as in the supplied template; no rows were imported",400);var detail=detailTables.FirstOrDefault();J.Require(h is not null&&detail is not null,"This file does not match the supplied CR format. Use Client/Date/Project/Requested by/Change Request No and Sl #/Client Requirement/Remarks tables",400);return(h!,detail!);}
 public static JsonObject Read(byte[] bytes,JsonArray? previous=null){var d=Document(bytes);var (h,t)=FormTables(d);var header=new JsonObject();foreach(var row in h.Elements(W+"tr")){var cells=row.Elements(W+"tc").ToList();if(cells.Count<2)continue;string key=Label(Text(cells[0])),value=Text(cells[1]);J.Require(value.Length<=1000,"A document header value is too long",400);string field=key switch{"client"=>"clientName","date"=>"date","project"=>"projectName","requestedby"=>"requestedBy",_=>key.StartsWith("changerequestno")?"externalNumber":""};if(field!="")header[field]=value;}
 var (number,revision)=SplitNumber(J.S(header,"externalNumber"));header["externalNumber"]=number;header["documentRevision"]=revision;var warnings=new JsonArray();if(DateOnly.TryParse(J.S(header,"date"),CultureInfo.GetCultureInfo("en-GB"),DateTimeStyles.None,out var date))header["date"]=date.ToString("yyyy-MM-dd");else warnings.Add("Choose a valid document date");
 string module="";var points=new JsonArray();foreach(var row in t.Elements(W+"tr").Skip(1)){var cells=row.Elements(W+"tc").ToList();if(cells.Count==0)continue;string first=Text(cells[0]);if(Regex.IsMatch(first,@"^Module\s*:",RegexOptions.IgnoreCase)){module=Regex.Replace(first,@"^Module\s*:\s*","",RegexOptions.IgnoreCase).Trim();continue;}J.Require(cells.Count==3,"Each form row must have Sl #, Client Requirement and Remarks cells; no rows were imported",400);var lines=Text(cells[1]).Split('\n').Select(x=>x.Trim()).Where(x=>x!="").ToList();if(lines.Count==0){J.Require(first==""&&Text(cells[2])=="","Requirement row "+first+" is empty. Complete or remove it before importing",400);continue;}var match=Regex.Match(lines[0],@"^Form\s*:\s*(.+)$",RegexOptions.IgnoreCase);J.Require(match.Success,"Row "+first+": first requirement line must start with Form : followed by the form name; no rows were imported",400);string form=match.Groups[1].Value.Trim(),changes=string.Join("\n",lines.Skip(1));var old=previous?.OfType<JsonObject>().Where(p=>NumberKey(J.S(p,"module"))==NumberKey(module)&&NumberKey(J.S(p,"formName"))==NumberKey(form)).ToList();if(old?.Count!=1)old=previous?.OfType<JsonObject>().Where(p=>J.S(p,"serial")==first&&NumberKey(J.S(p,"module"))==NumberKey(module)).ToList();if(old?.Count!=1)old=previous?.OfType<JsonObject>().Where(p=>J.S(p,"serial")==first).ToList();string id=old?.Count==1?J.S(old[0],"id"):"P"+Guid.NewGuid().ToString("N")[..12];points.Add(new JsonObject{["id"]=id,["serial"]=first,["module"]=module,["formName"]=form,["text"]=changes,["remarks"]=Text(cells[2])});}
 J.Require(points.Count is >0 and <=50,"Document must contain 1–50 Form : rows under Module : headings",400);return new JsonObject{["header"]=header,["points"]=points,["warnings"]=warnings,["html"]=Html(d)};}
 static void Cell(XElement cell,string value){var prototype=cell.Elements(W+"p").FirstOrDefault();var pPr=prototype?.Element(W+"pPr");cell.Elements().Where(e=>e.Name!=W+"tcPr").Remove();foreach(var line in value.Replace("\r","").Split('\n')){var p=new XElement(W+"p");if(pPr is not null)p.Add(new XElement(pPr));p.Add(new XElement(W+"r",new XElement(W+"t",new XAttribute(XNamespace.Xml+"space","preserve"),line)));cell.Add(p);}}
 public static byte[] Rewrite(byte[] original,JsonObject header,JsonArray points){var d=Document(original);var (h,t)=FormTables(d);foreach(var row in h.Elements(W+"tr")){var c=row.Elements(W+"tc").ToList();if(c.Count<2)continue;string key=Label(Text(c[0]));string? value=key switch{"client"=>J.S(header,"clientName"),"date"=>DateOnly.TryParseExact(J.S(header,"date"),"yyyy-MM-dd",out var day)?day.ToString("dd-MMM-yyyy",CultureInfo.InvariantCulture):J.S(header,"date"),"project"=>J.S(header,"projectName"),"requestedby"=>J.S(header,"requestedBy"),_=>key.StartsWith("changerequestno")?J.S(header,"externalNumber")+(J.S(header,"documentRevision")==""?"":" Rev "+J.S(header,"documentRevision")):null};if(value is not null)Cell(c[1],value);}
 var rows=t.Elements(W+"tr").ToList();var detail=rows.Skip(1).First(r=>r.Elements(W+"tc").Count()>=3&&!Text(r.Elements(W+"tc").First()).StartsWith("Module",StringComparison.OrdinalIgnoreCase));var moduleRow=rows.Skip(1).FirstOrDefault(r=>Regex.IsMatch(Text(r.Elements(W+"tc").First()),@"^Module\s*:",RegexOptions.IgnoreCase));var detailTemplate=new XElement(detail);var moduleTemplate=moduleRow is null?null:new XElement(moduleRow);rows.Skip(1).Remove();string previousModule="";int serial=0;foreach(var point in points.OfType<JsonObject>()){var module=J.S(point,"module");if(module!=previousModule){var row=moduleTemplate is null?new XElement(W+"tr",new XElement(W+"tc",new XElement(W+"tcPr",new XElement(W+"gridSpan",new XAttribute(W+"val",2)))),new XElement(W+"tc")):new XElement(moduleTemplate);var cells=row.Elements(W+"tc").ToList();Cell(cells[0],"Module: "+module);foreach(var c in cells.Skip(1))Cell(c,"");t.Add(row);previousModule=module;}var next=new XElement(detailTemplate);var cellsNext=next.Elements(W+"tc").ToList();Cell(cellsNext[0],(++serial).ToString("00"));Cell(cellsNext[1],"Form : "+J.S(point,"formName")+"\n"+J.S(point,"text"));Cell(cellsNext[2],J.S(point,"remarks"));t.Add(next);}
 using var input=new ZipArchive(new MemoryStream(original),ZipArchiveMode.Read);using var output=new MemoryStream();using(var zip=new ZipArchive(output,ZipArchiveMode.Create,true)){foreach(var item in input.Entries){var target=zip.CreateEntry(item.FullName,CompressionLevel.Optimal);using var write=target.Open();if(item.FullName=="word/document.xml")d.Save(write,SaveOptions.DisableFormatting);else{using var read=item.Open();read.CopyTo(write);}}}var bytes=output.ToArray();J.Require(bytes.Length<=5242880,"Updated Word file exceeds 5 MB",400);return bytes;}
 public static string PreviewHtml(byte[] bytes)=>Html(Document(bytes));
 static string Html(XDocument d){var paragraphIds=d.Descendants(W+"p").Where(p=>ParagraphText(p).Trim()!="").Select((p,i)=>(p,id:i+1)).ToDictionary(x=>x.p,x=>x.id);string Render(XElement el){if(el.Name==W+"p"){string text=ParagraphText(el);if(text.Trim()=="")return "";return "<p data-doc-paragraph=\"D"+paragraphIds[el]+"\"><small>D"+paragraphIds[el]+"</small> "+WebUtility.HtmlEncode(text)+"</p>";}if(el.Name==W+"tbl")return "<table>"+string.Concat(el.Elements(W+"tr").Select(Render))+"</table>";if(el.Name==W+"tr")return "<tr>"+string.Concat(el.Elements(W+"tc").Select(Render))+"</tr>";if(el.Name==W+"tc"){int span=int.TryParse(el.Element(W+"tcPr")?.Element(W+"gridSpan")?.Attribute(W+"val")?.Value,out var n)?Math.Clamp(n,1,20):1;return "<td colspan=\""+span+"\">"+string.Concat(el.Elements().Where(e=>e.Name==W+"p"||e.Name==W+"tbl").Select(Render))+"</td>";}return "";}return "<article class=\"cr-word-page\">"+string.Concat(d.Root!.Element(W+"body")!.Elements().Select(Render))+"</article>";}
}
